import { PlaneGeometry, MeshBasicNodeMaterial, Mesh, Texture } from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * Creates a textured plane for the "Collection card 1" UI element.
 * Loads the texture via ctx.textureLoader, applies it to a plane geometry,
 * and positions it according to the scene placement spec.
 *
 * @param {Object} config - Node configuration (includes scenePosition, textContent, cinematicPrimitives, etc.)
 * @param {Object} ctx - Node context (textureLoader, fontAtlas, primitives, etc.)
 * @returns {THREE.Object3D} - The created plane mesh with userData.cleanup
 */
export default function createNode(config, ctx) {
  const { textureLoader } = ctx;

  // Default dimensions based on texture aspect ratio (512x320 ≈ 1.6)
  const width = 2;
  const height = width * (320 / 512); // ≈1.25

  const geometry = new PlaneGeometry(width, height);
  let material;
  let mesh;

  try {
    const texture = textureLoader('/prism-mock/home/nodes/cta-hero-isolated.png');

    material = new MeshBasicNodeMaterial({
      map: texture,
      side: 2, // double side for flat card appearance
    });

    mesh = new Mesh(geometry, material);
  } catch (err) {
    // Fallback: create a plain opaque surface if texture fails to load
    console.warn('Collection card texture load failed, using fallback color', err);
    material = new MeshBasicNodeMaterial({ color: '#16161d' });
    mesh = new Mesh(geometry, material);
  }

  // Position from scene placement spec
  const pos = config.scenePosition || { x: -3.2, y: -0.3, z: 0 };
  mesh.position.set(pos.x, pos.y, pos.z);

  // Rotation and scale from spec (defaults if not provided)
  const rot = config.sceneRotation || { x: 0, y: 0, z: 0 };
  mesh.rotation.set(rot.x, rot.y, rot.z);
  const scale = config.sceneScale || { x: 1, y: 1, z: 1 };
  mesh.scale.set(scale.x, scale.y, scale.z);

  // Attach empty handlers (no interactions defined)
  mesh.userData.handlers = {};

  // Cleanup function: dispose geometry, material, and texture if owned
  mesh.userData.cleanup = () => {
    geometry.dispose();
    if (material.map) material.map.dispose();
    material.dispose();
  };

  return mesh;
}
